const fs = require('fs');
const path = require('path');

// ============================================================
// generar_467_perfil_completo.js
// ============================================================
// El chat aprende TODO lo que hay sobre la mascota, no solo lo que se
// registra a diario. Nueve temas nuevos:
//
//   PERFIL       raza, edad, sexo, estado reproductivo, color, chip
//   ALERGIAS     con la advertencia de mencionarlo a cualquier vet
//   CELOS        los ultimos y, con dos o mas, cuando vendria el proximo
//   LABORATORIO  los examenes guardados (sin interpretarlos)
//   TEMPERATURA  la ultima registrada, y si esta fuera de rango
//   RESPIRACION  la ultima registrada, y si esta fuera de rango
//   REVISION     cuando fue la ultima revision corporal
//   MOMENTOS     los hitos guardados
//   ENFERMEDADES los diagnosticos y sus proximos controles
//
// EJEMPLO
//   Tú: ¿cuáles son sus datos?
//   Chiqui: Lucy:
//           · Raza: Siamés
//           · Edad: 6 años y 5 meses
//           · Sexo: Hembra, esterilizado/a
//           · Peso: 4.2 kg (20 ago)
//           · ⚠️ Alergia: Pollo
//
// LA TEMPERATURA Y LA RESPIRACION dicen si el valor esta fuera de lo
// normal, pero NO diagnostican: nombran el rango y sugieren comentarlo.
//
// TRES ERRORES QUE ENCONTRE PROBANDO
//
//   La ñ desaparece al normalizar: escribi 'cuantos años' pero el
//   texto ya viene como "cuantos anos", asi que nunca calzaba.
//
//   "¿que temperatura TIENE?" caia en el consejo educativo en vez de
//   dar el dato. Se agrego "tiene" a las señales de pregunta por datos.
//
//   'cuanto respira' estaba en el consejo del corazon y se comia la
//   pregunta por el dato registrado.
//
// REQUISITO: script 466 desplegado.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const dChat = path.join(process.cwd(), RUTA_CHAT);
const dFlot = path.join(process.cwd(), RUTA_FLOT);
for (const [r, d] of [[RUTA_CHAT, dChat], [RUTA_FLOT, dFlot]]) {
  if (!fs.existsSync(d)) abortar('no se encontro ' + r + '.');
}

const actual = fs.readFileSync(dChat, 'utf8');
if (actual.includes("case 'celos'")) {
  abortar('el chat ya tiene esto. Parece que este script ya se corrio.');
}
if (!actual.includes('quiereHistorial')) {
  abortar('falta el script 466. Correlo primero.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

for (const r of ["case 'perfil'", "case 'alergias'", "case 'celos'", "case 'lab'",
                 "case 'temperatura'", "case 'respiracion'", "case 'revision'",
                 "case 'momentos'", "case 'enfermedades'", 'cuantos anos']) {
  if (!chat.includes(r)) abortar('el chat nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  los 9 temas nuevos estan en el chat');

for (const r of ["from('celos')", "from('examenes_lab')", "from('temperatura_corporal')",
                 "from('frecuencia_respiratoria')", "from('revisiones_corporales')",
                 "from('momentos')", "from('enfermedades')", 'perfil: {']) {
  if (!flot.includes(r)) abortar('el flotante nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  el flotante trae los datos nuevos');

// Ninguna consulta puede quedar sin filtro de mascota.
const queries = flot.match(/supabase\.from\('[a-z_]+'\)[\s\S]*?(?=,\n|\n\s*\])/g) || [];
const sinFiltro = queries.filter(q => !q.includes("eq('mascota_id'") && !q.includes("eq('user_id'"));
if (sinFiltro.length > 0) {
  abortar(sinFiltro.length + ' consulta(s) sin filtro de mascota. No se escribio nada.');
}
console.log('  OK  las ' + queries.length + ' consultas filtran por mascota');

fs.writeFileSync(dChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(dFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);
console.log('');
console.log('AVISO: si alguna de las tablas nuevas no existe en tu Supabase,');
console.log('esa consulta devuelve vacio y el chat dice que no tiene el dato.');
console.log('No rompe nada, pero avisale a Claude si notas algo raro.');
console.log('');
console.log('Listo. Prueba con "¿cuales son sus datos?" y "¿que raza es?".');
